#!/usr/bin/env node
// @ts-check
/**
 * scripts/gen-gateway-schema.mjs — generate the Gateway handshake constants from
 * config/gateway.json.
 *
 * The Gateway (TypeScript) and the add-on (Python) must agree on the protocol
 * version, handshake fields, instance kinds and WebSocket path. This generator
 * renders both sides from the single JSON source:
 *   - runtime/transport/gateway-schema.generated.ts
 *   - addon/dsh_blender_bridge/gateway_schema.py
 *
 * scripts/check-gateway-schema.mjs (npm run check:gateway-schema) fails when a
 * generated file is missing, stale, or hand-edited.
 */
import crypto from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = path.dirname(fileURLToPath(import.meta.url))
export const DEFAULT_ROOT = path.resolve(HERE, '..')
export const SCHEMA_FILE = 'config/gateway.json'
export const GENERATED_FILES = [
  'runtime/transport/gateway-schema.generated.ts',
  'addon/dsh_blender_bridge/gateway_schema.py',
]

const fail = (message) => {
  console.error('gen-gateway-schema: ' + message)
  process.exit(1)
}

const isNonEmptyString = (value) => typeof value === 'string' && value.length > 0
const isPositiveInteger = (value) => Number.isInteger(value) && value > 0

export function validateGatewaySchema(config) {
  const failures = []
  if (!config || typeof config !== 'object') return ['top-level value must be an object']
  if (config.version !== 1) failures.push('version must be 1')
  if (!Array.isArray(config.generated) || config.generated.join(',') !== GENERATED_FILES.join(','))
    failures.push('generated must list ' + GENERATED_FILES.join(' + '))
  const addon = config.addon
  if (!addon || typeof addon !== 'object') {
    failures.push('addon must be an object')
  } else {
    if (addon.protocol !== 12)
      failures.push('addon.protocol must be 12 (3.1 breaking wire protocol)')
    if (!isNonEmptyString(addon.version)) failures.push('addon.version must be a non-empty string')
    if (
      !Array.isArray(addon.kinds) ||
      addon.kinds.length === 0 ||
      addon.kinds.some((kind) => !isNonEmptyString(kind))
    )
      failures.push('addon.kinds must be a non-empty array of strings')
    if (!isNonEmptyString(addon.wsPath) || !addon.wsPath.startsWith('/'))
      failures.push('addon.wsPath must start with /')
    for (const key of ['heartbeatMs', 'deadMs', 'maxMessageBytes']) {
      if (!isPositiveInteger(addon[key]))
        failures.push('addon.' + key + ' must be a positive integer')
    }
    if (
      isPositiveInteger(addon.heartbeatMs) &&
      isPositiveInteger(addon.deadMs) &&
      addon.deadMs <= addon.heartbeatMs
    )
      failures.push('addon.deadMs must be greater than addon.heartbeatMs')
  }
  const gateway = config.gateway
  if (!gateway || typeof gateway !== 'object' || !isPositiveInteger(gateway.defaultPort))
    failures.push('gateway.defaultPort must be a positive integer')
  const handshake = config.handshake
  if (!handshake || typeof handshake !== 'object') {
    failures.push('handshake must be an object')
  } else {
    const required = handshake.requiredFields
    if (
      !Array.isArray(required) ||
      required.length === 0 ||
      required.some((field) => !isNonEmptyString(field))
    )
      failures.push('handshake.requiredFields must be a non-empty array of strings')
    else {
      const unique = new Set(required)
      if (unique.size !== required.length)
        failures.push('handshake.requiredFields must not repeat fields')
      if (!unique.has('instanceId') || !unique.has('protocol') || !unique.has('capabilities'))
        failures.push('handshake.requiredFields must include instanceId, protocol and capabilities')
    }
  }
  return failures
}

function header(hash) {
  return [
    'AUTO-GENERATED FILE - generated by scripts/gen-gateway-schema.mjs; do not edit.',
    'Source: config/gateway.json',
    'Regenerate: node scripts/gen-gateway-schema.mjs',
    'source-sha256: ' + hash,
  ]
}

function renderTs(config, hash) {
  const addon = config.addon
  const fields = config.handshake.requiredFields
  return [
    '// ' + header(hash).join('\n// '),
    '',
    'export const GATEWAY_SCHEMA_VERSION = ' + config.version,
    'export const ADDON_PROTOCOL_VERSION = ' + addon.protocol,
    "export const ADDON_VERSION = '" + addon.version + "'",
    'export const ADDON_KINDS = [' +
      addon.kinds.map((kind) => "'" + kind + "'").join(', ') +
      '] as const',
    'export type AddonKind = (typeof ADDON_KINDS)[number]',
    "export const ADDON_WS_PATH = '" + addon.wsPath + "'",
    'export const HEARTBEAT_MS = ' + addon.heartbeatMs,
    'export const HEARTBEAT_DEAD_MS = ' + addon.deadMs,
    'export const MAX_MESSAGE_BYTES = ' + addon.maxMessageBytes,
    'export const GATEWAY_DEFAULT_PORT = ' + config.gateway.defaultPort,
    'export const HANDSHAKE_REQUIRED_FIELDS = [' +
      fields.map((field) => "'" + field + "'").join(', ') +
      '] as const',
    '',
  ].join('\n')
}

function renderPy(config, hash) {
  const addon = config.addon
  const fields = config.handshake.requiredFields
  const quote = (value) => JSON.stringify(value)
  return [
    '"""Gateway handshake constants generated from config/gateway.json.',
    '',
    ...header(hash).map((line) => ' ' + line),
    '"""',
    '',
    'GATEWAY_SCHEMA_VERSION = ' + config.version,
    'ADDON_PROTOCOL_VERSION = ' + addon.protocol,
    'ADDON_VERSION = ' + quote(addon.version),
    'ADDON_KINDS = (' +
      addon.kinds.map(quote).join(', ') +
      (addon.kinds.length === 1 ? ',' : '') +
      ')',
    'ADDON_WS_PATH = ' + quote(addon.wsPath),
    'HEARTBEAT_MS = ' + addon.heartbeatMs,
    'HEARTBEAT_DEAD_MS = ' + addon.deadMs,
    'MAX_MESSAGE_BYTES = ' + addon.maxMessageBytes,
    'GATEWAY_DEFAULT_PORT = ' + config.gateway.defaultPort,
    'HANDSHAKE_REQUIRED_FIELDS = (' +
      fields.map(quote).join(', ') +
      (fields.length === 1 ? ',' : '') +
      ')',
    '',
  ].join('\n')
}

export function generateGatewaySchema(root = DEFAULT_ROOT) {
  const sourcePath = path.join(root, SCHEMA_FILE)
  const source = fs.readFileSync(sourcePath, 'utf8')
  let config
  try {
    config = JSON.parse(source)
  } catch (error) {
    throw new Error(
      SCHEMA_FILE +
        ' is not valid JSON: ' +
        (error instanceof Error ? error.message : String(error)),
      { cause: error },
    )
  }
  const failures = validateGatewaySchema(config)
  if (failures.length) throw new Error('invalid ' + SCHEMA_FILE + ': ' + failures.join('; '))
  const hash = crypto.createHash('sha256').update(source).digest('hex')
  const contents = [renderTs(config, hash), renderPy(config, hash)]
  return {
    hash,
    config,
    files: GENERATED_FILES.map((file, index) => ({ file, content: contents[index] })),
  }
}

export function writeGatewaySchema(root = DEFAULT_ROOT) {
  const generated = generateGatewaySchema(root)
  for (const file of generated.files) {
    const target = path.join(root, file.file)
    fs.mkdirSync(path.dirname(target), { recursive: true })
    fs.writeFileSync(target, file.content, 'utf8')
  }
  return generated
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const generated = writeGatewaySchema()
    console.log(
      'gen-gateway-schema: wrote ' +
        generated.files.length +
        ' files (protocol ' +
        generated.config.addon.protocol +
        ', sha256 ' +
        generated.hash.slice(0, 12) +
        ')',
    )
  } catch (error) {
    fail(error instanceof Error ? error.message : String(error))
  }
}
